import sys

def igra(start, i):
    n = start[i]
    start[i] = 0
    if n == 0:
        return 0
    add_to_all = n // 14
    n = n % 14
    for j in range(14):
        start[j] += add_to_all
    current = i
    while n != 0:
        current = (current + 1) % 14
        start[current] += 1
        n -= 1
    result = 0
    for j in range(14):
        if start[j] % 2 == 0:
            result += start[j]
    return result

def main():
    line = sys.stdin.readline()
    arr_start_strings = line.strip().split()
    original_start = [int(v) for v in arr_start_strings]

    max_score = 0
    for i in range(14):
        start_copy = original_start[:]
        score = igra(start_copy, i)
        if score > max_score:
            max_score = score
    print(max_score)

if __name__ == "__main__":
    main()

